with a as(select * from public.authors where open_library_id=any(array['OL1428806A','OL34328A','OL40784A','OL24470A','OL7213954A','OL4135199A','OL7831882A','OL29227A']::text[]) or id=any(array[1112,380,1549,239]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789025912673','9789024553952','9789022537329','9789089681874','9789029065719','9789022561508','9789022557792','9789046112786']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL37575384W','OL52940W','OL554751W','OL5805250W','OL5805255W','OL85743W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['theanxiousgeneration','generatieangststoornis','thehardway','bloedgeld','mistressoftheempire','vrouwevanhetkeizerrijk','hunted','onveilig','untamed','ontembaar','moonraker']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['theanxiousgeneration','generatieangststoornis','thehardway','bloedgeld','mistressoftheempire','vrouwevanhetkeizerrijk','hunted','onveilig','untamed','ontembaar','moonraker']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987130001 and 987130999),'editions',(select count(*) from public.editions where id between 987230001 and 987230999),'authors',(select count(*) from public.authors where id between 987330001 and 987330999))) as preflight;
